53	size_t ptls_asn1_error_message(char const *error_label, size_t bytes_max, size_t byte_index, int level,
54	                               ptls_minicrypto_log_ctx_t *log_ctx)
55	{
56	    if (log_ctx != NULL) {
57	        ptls_asn1_print_indent(level, log_ctx);
58	        log_ctx->fn(log_ctx->ctx, "Error: %s (near position: %d (0x%x) out of %d)", error_label, (int)byte_index,
59	                    (uint32_t)byte_index, (int)bytes_max);
60	    }
61	    return byte_index;
