64	void ptls_asn1_dump_content(const uint8_t *bytes, size_t bytes_max, size_t byte_index, ptls_minicrypto_log_ctx_t *log_ctx)
65	{
66	    if (log_ctx != NULL && bytes_max > byte_index) {
67	        size_t nb_bytes = bytes_max - byte_index;
68	
69	        log_ctx->fn(log_ctx->ctx, " ");
70	
71	        for (size_t i = 0; i < 16 && i < nb_bytes; i++) {
72	            log_ctx->fn(log_ctx->ctx, "%02x", bytes[byte_index + i]);
73	        }
74	
75	        if (nb_bytes > 16) {
76	            log_ctx->fn(log_ctx->ctx, "...");
77	        }
78	    }
79	}
80	
81	size_t ptls_asn1_read_type(const uint8_t *bytes, size_t bytes_max, int *structure_bit, int *type_class, uint32_t *type_number,
82	                           int *decode_error, int level, ptls_minicrypto_log_ctx_t *log_ctx)
83	{
84	    /* Get the type byte */
85	    size_t byte_index = 1;
86	    uint8_t first_byte = bytes[0];
87	    *structure_bit = (first_byte >> 5) & 1;
88	    *type_class = (first_byte >> 6) & 3;
89	    *type_number = first_byte & 31;
90	
91	    if (*type_number == 31) {
92	        uint32_t long_type = 0;
93	        const uint32_t type_number_limit = 0x07FFFFFFF;
94	        int next_byte;
95	        int end_found = 0;
96	
97	        while (byte_index < bytes_max && long_type <= type_number_limit) {
98	            next_byte = bytes[byte_index++];
99	            long_type <<= 7;
100	            long_type |= next_byte & 127;
101	            if ((next_byte & 128) == 0) {
102	                end_found = 1;
103	                break;
104	            }
105	        }
106	
107	        if (end_found) {
108	            *type_number = long_type;
109	        } else {
110	            /* This is an error */
111	            byte_index = ptls_asn1_error_message("Incorrect type coding", bytes_max, byte_index, level, log_ctx);
112	            *decode_error = PTLS_ERROR_BER_MALFORMED_TYPE;
113	        }
114	    }
115	
116	    return byte_index;
117	}
118	
119	void ptls_asn1_print_type(int type_class, uint32_t type_number, int level, ptls_minicrypto_log_ctx_t *log_ctx)
120	{
121	    /* Print the type */
122	    ptls_asn1_print_indent(level, log_ctx);
123	    if (type_class == 0 && type_number < nb_asn1_universal_types) {
124	        log_ctx->fn(log_ctx->ctx, "%s", asn1_universal_types[type_number]);
125	    } else if (type_class == 2) {
126	        log_ctx->fn(log_ctx->ctx, "[%d]", type_number);
127	    } else {
128	        log_ctx->fn(log_ctx->ctx, "%s[%d]", asn1_type_classes[type_class], type_number);
129	    }
130	}
131	
132	size_t ptls_asn1_read_length(const uint8_t *bytes, size_t bytes_max, size_t byte_index, uint32_t *length, int *indefinite_length,
133	                             size_t *last_byte, int *decode_error, int level, ptls_minicrypto_log_ctx_t *log_ctx)
134	{
135	    int length_of_length = 0;
136	
137	    *indefinite_length = 0;
138	    *length = 0;
139	    *last_byte = bytes_max;
140	
141	    if (byte_index < bytes_max) {
142	        *length = bytes[byte_index++];
143	        if ((*length & 128) != 0) {
144	            length_of_length = *length & 127;
145	            *length = 0;
146	
147	            if (byte_index + length_of_length >= bytes_max) {
148	                /* This is an error */
149	                byte_index = ptls_asn1_error_message("Incorrect length coding", bytes_max, byte_index, level, log_ctx);
150	                *decode_error = PTLS_ERROR_BER_MALFORMED_LENGTH;
151	            } else {
152	                for (int i = 0; i < length_of_length && byte_index < bytes_max; i++) {
153	                    *length <<= 8;
154	                    *length |= bytes[byte_index++];
155	                }
156	
157	                if (length_of_length == 0) {
158	                    *last_byte = bytes_max;
159	                    *indefinite_length = 1;
160	                } else {
161	                    *last_byte = byte_index + *length;
162	                }
163	            }
164	        } else {
165	            *last_byte = byte_index + *length;
166	        }
167	
168	        if (*decode_error == 0) {
169	            /* TODO: verify that the length makes sense */
170	            if (*last_byte > bytes_max) {
171	                byte_index = ptls_asn1_error_message("Length larger than message", bytes_max, byte_index, level, log_ctx);
172	                *decode_error = PTLS_ERROR_BER_EXCESSIVE_LENGTH;
173	            }
174	        }
175	    }
176	
177	    return byte_index;
178	}
